from pathlib import Path

ROOT = Path(__file__).resolve().parent

def write_file(relative_path: str, content: str):
    path = ROOT / relative_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.strip() + '\n', encoding='utf-8')
    print(f'updated: {relative_path}')

FILES = {
    'backend/app/llm_provider.py': '\nimport json\nimport os\nimport re\nimport urllib.error\nimport urllib.request\nfrom pathlib import Path\nfrom typing import Any, Dict, Optional, Tuple\n\n\ntry:\n    from dotenv import load_dotenv\n\n    ROOT_DIR = Path(__file__).resolve().parents[2]\n    load_dotenv(ROOT_DIR / ".env")\n    load_dotenv(ROOT_DIR / "backend" / ".env")\nexcept Exception:\n    pass\n\n\nDEFAULT_PROVIDER = os.getenv("LLM_PROVIDER", "ollama").lower()\n\nOPENAI_API_KEY = os.getenv("OPENAI_API_KEY", "")\nOPENAI_MODEL = os.getenv("OPENAI_MODEL", "gpt-4o-mini")\n\nGEMINI_API_KEY = os.getenv("GEMINI_API_KEY", "")\nGEMINI_MODEL = os.getenv("GEMINI_MODEL", "gemini-1.5-flash")\n\nOLLAMA_BASE_URL = os.getenv("OLLAMA_BASE_URL", "http://localhost:11434").rstrip("/")\nOLLAMA_MODEL = os.getenv("OLLAMA_MODEL", "llama3.1")\n\n\ndef _json_request(url: str, payload: Optional[Dict[str, Any]] = None, headers: Optional[Dict[str, str]] = None, timeout: int = 25) -> Dict[str, Any]:\n    data = None\n    if payload is not None:\n        data = json.dumps(payload).encode("utf-8")\n\n    request = urllib.request.Request(\n        url,\n        data=data,\n        headers=headers or {},\n        method="POST" if payload is not None else "GET",\n    )\n\n    with urllib.request.urlopen(request, timeout=timeout) as response:\n        raw = response.read().decode("utf-8")\n        return json.loads(raw)\n\n\ndef _extract_json_object(text: str) -> Optional[Dict[str, Any]]:\n    if not text:\n        return None\n\n    stripped = text.strip()\n\n    try:\n        return json.loads(stripped)\n    except json.JSONDecodeError:\n        pass\n\n    fenced = re.search(r"```(?:json)?\\s*(\\{.*?\\})\\s*```", stripped, re.DOTALL)\n    if fenced:\n        try:\n            return json.loads(fenced.group(1))\n        except json.JSONDecodeError:\n            pass\n\n    start = stripped.find("{")\n    end = stripped.rfind("}")\n\n    if start != -1 and end != -1 and end > start:\n        candidate = stripped[start:end + 1]\n        try:\n            return json.loads(candidate)\n        except json.JSONDecodeError:\n            return None\n\n    return None\n\n\ndef get_llm_status() -> Dict[str, Any]:\n    ollama_running = False\n    ollama_models = []\n\n    try:\n        result = _json_request(f"{OLLAMA_BASE_URL}/api/tags", timeout=3)\n        ollama_running = True\n        ollama_models = [item.get("name") for item in result.get("models", [])]\n    except Exception:\n        ollama_running = False\n\n    return {\n        "default_provider": DEFAULT_PROVIDER,\n        "providers": {\n            "ollama": {\n                "configured": True,\n                "running": ollama_running,\n                "base_url": OLLAMA_BASE_URL,\n                "model": OLLAMA_MODEL,\n                "available_models": ollama_models,\n            },\n            "openai": {\n                "configured": bool(OPENAI_API_KEY),\n                "model": OPENAI_MODEL,\n            },\n            "gemini": {\n                "configured": bool(GEMINI_API_KEY),\n                "model": GEMINI_MODEL,\n            },\n        },\n    }\n\n\ndef _call_ollama(prompt: str) -> Tuple[Optional[str], Optional[str]]:\n    try:\n        response = _json_request(\n            f"{OLLAMA_BASE_URL}/api/generate",\n            payload={\n                "model": OLLAMA_MODEL,\n                "prompt": prompt,\n                "stream": False,\n                "format": "json",\n            },\n            headers={"Content-Type": "application/json"},\n            timeout=45,\n        )\n        return response.get("response", ""), None\n    except Exception as exc:\n        return None, f"Ollama call failed: {exc}"\n\n\ndef _call_openai(system_prompt: str, user_prompt: str) -> Tuple[Optional[str], Optional[str]]:\n    if not OPENAI_API_KEY:\n        return None, "OPENAI_API_KEY is missing."\n\n    try:\n        response = _json_request(\n            "https://api.openai.com/v1/chat/completions",\n            payload={\n                "model": OPENAI_MODEL,\n                "messages": [\n                    {"role": "system", "content": system_prompt},\n                    {"role": "user", "content": user_prompt},\n                ],\n                "temperature": 0.8,\n                "response_format": {"type": "json_object"},\n            },\n            headers={\n                "Content-Type": "application/json",\n                "Authorization": f"Bearer {OPENAI_API_KEY}",\n            },\n            timeout=45,\n        )\n\n        content = response["choices"][0]["message"]["content"]\n        return content, None\n    except Exception as exc:\n        return None, f"OpenAI call failed: {exc}"\n\n\ndef _call_gemini(system_prompt: str, user_prompt: str) -> Tuple[Optional[str], Optional[str]]:\n    if not GEMINI_API_KEY:\n        return None, "GEMINI_API_KEY is missing."\n\n    try:\n        url = (\n            f"https://generativelanguage.googleapis.com/v1beta/models/"\n            f"{GEMINI_MODEL}:generateContent?key={GEMINI_API_KEY}"\n        )\n\n        response = _json_request(\n            url,\n            payload={\n                "contents": [\n                    {\n                        "parts": [\n                            {\n                                "text": f"{system_prompt}\\n\\n{user_prompt}\\n\\nReturn only valid JSON."\n                            }\n                        ]\n                    }\n                ],\n                "generationConfig": {\n                    "temperature": 0.8,\n                    "responseMimeType": "application/json",\n                },\n            },\n            headers={"Content-Type": "application/json"},\n            timeout=45,\n        )\n\n        content = response["candidates"][0]["content"]["parts"][0]["text"]\n        return content, None\n    except Exception as exc:\n        return None, f"Gemini call failed: {exc}"\n\n\ndef generate_json_with_llm(system_prompt: str, user_prompt: str, provider: Optional[str] = None) -> Dict[str, Any]:\n    selected_provider = (provider or DEFAULT_PROVIDER or "ollama").lower()\n\n    full_prompt = (\n        f"{system_prompt}\\n\\n"\n        f"{user_prompt}\\n\\n"\n        "Return only one valid JSON object. Do not include markdown."\n    )\n\n    if selected_provider == "off":\n        return {\n            "ok": False,\n            "provider": "off",\n            "data": None,\n            "error": "LLM provider is off.",\n        }\n\n    if selected_provider == "openai":\n        text, error = _call_openai(system_prompt, user_prompt)\n    elif selected_provider == "gemini":\n        text, error = _call_gemini(system_prompt, user_prompt)\n    else:\n        selected_provider = "ollama"\n        text, error = _call_ollama(full_prompt)\n\n    if error:\n        return {\n            "ok": False,\n            "provider": selected_provider,\n            "data": None,\n            "error": error,\n        }\n\n    parsed = _extract_json_object(text or "")\n\n    if parsed is None:\n        return {\n            "ok": False,\n            "provider": selected_provider,\n            "data": None,\n            "error": "LLM returned text, but no valid JSON object could be parsed.",\n            "raw": text,\n        }\n\n    return {\n        "ok": True,\n        "provider": selected_provider,\n        "data": parsed,\n        "error": None,\n    }\n',
    'backend/app/mock_generator.py': '\nimport random\nfrom typing import Dict, Optional\n\nfrom .llm_provider import generate_json_with_llm\n\n\nTASK_FALLBACKS = [\n    {\n        "title": "Customer payment failed after checkout",\n        "description": "Customer says the payment failed during checkout but the amount was debited from their account.",\n        "priority": "high",\n        "category": "payment",\n        "required_skills": ["payments", "billing", "customer_support"],\n        "sla_minutes": 60,\n    },\n    {\n        "title": "Partner API latency issue",\n        "description": "A partner integration reports slow API responses and intermittent timeout errors in production.",\n        "priority": "urgent",\n        "category": "technical",\n        "required_skills": ["technical_support", "api", "debugging"],\n        "sla_minutes": 45,\n    },\n    {\n        "title": "Refund request for duplicate charge",\n        "description": "Customer was charged twice for the same order and wants an urgent refund update.",\n        "priority": "high",\n        "category": "billing",\n        "required_skills": ["billing", "refunds", "customer_support"],\n        "sla_minutes": 60,\n    },\n    {\n        "title": "User account locked after failed login attempts",\n        "description": "Customer cannot access their account because it was locked after multiple login attempts.",\n        "priority": "medium",\n        "category": "account",\n        "required_skills": ["account_management", "customer_support"],\n        "sla_minutes": 120,\n    },\n    {\n        "title": "Customer needs help using analytics dashboard",\n        "description": "Customer wants guidance on how to read reports and export dashboard metrics.",\n        "priority": "low",\n        "category": "general",\n        "required_skills": ["customer_support"],\n        "sla_minutes": 240,\n    },\n]\n\n\nRESOURCE_FALLBACKS = [\n    {\n        "name": "Maya",\n        "status": "idle",\n        "current_tasks": 0,\n        "max_tasks": 4,\n        "shift_start": "09:00",\n        "shift_end": "18:00",\n        "skills": ["payments", "billing", "customer_support"],\n        "handled_categories": ["payment", "billing"],\n        "experience_level": 4,\n        "success_rate": 0.91,\n        "avg_resolution_minutes": 38,\n    },\n    {\n        "name": "Kabir",\n        "status": "available",\n        "current_tasks": 1,\n        "max_tasks": 4,\n        "shift_start": "10:00",\n        "shift_end": "19:00",\n        "skills": ["technical_support", "api", "debugging", "backend"],\n        "handled_categories": ["technical"],\n        "experience_level": 5,\n        "success_rate": 0.94,\n        "avg_resolution_minutes": 42,\n    },\n    {\n        "name": "Isha",\n        "status": "idle",\n        "current_tasks": 0,\n        "max_tasks": 3,\n        "shift_start": "08:00",\n        "shift_end": "17:00",\n        "skills": ["account_management", "customer_support"],\n        "handled_categories": ["account", "general"],\n        "experience_level": 3,\n        "success_rate": 0.86,\n        "avg_resolution_minutes": 52,\n    },\n    {\n        "name": "Dev",\n        "status": "busy",\n        "current_tasks": 2,\n        "max_tasks": 5,\n        "shift_start": "14:00",\n        "shift_end": "22:00",\n        "skills": ["billing", "refunds", "customer_support"],\n        "handled_categories": ["billing", "refund"],\n        "experience_level": 4,\n        "success_rate": 0.89,\n        "avg_resolution_minutes": 46,\n    },\n]\n\n\ndef _normalize_task(data: Dict, source_provider: str, llm_used: bool) -> Dict:\n    fallback = random.choice(TASK_FALLBACKS)\n\n    required_skills = data.get("required_skills", fallback["required_skills"])\n    if isinstance(required_skills, str):\n        required_skills = [item.strip().lower() for item in required_skills.split(",") if item.strip()]\n\n    priority = str(data.get("priority", fallback["priority"])).lower()\n    if priority not in {"urgent", "high", "medium", "low"}:\n        priority = fallback["priority"]\n\n    return {\n        "title": str(data.get("title", fallback["title"])),\n        "description": str(data.get("description", fallback["description"])),\n        "priority": priority,\n        "category": str(data.get("category", fallback["category"])).lower(),\n        "required_skills": required_skills,\n        "sla_minutes": int(data.get("sla_minutes", fallback["sla_minutes"]) or fallback["sla_minutes"]),\n        "source_provider": source_provider,\n        "llm_used": llm_used,\n    }\n\n\ndef _normalize_resource(data: Dict, source_provider: str, llm_used: bool) -> Dict:\n    fallback = random.choice(RESOURCE_FALLBACKS)\n\n    skills = data.get("skills", fallback["skills"])\n    if isinstance(skills, str):\n        skills = [item.strip().lower() for item in skills.split(",") if item.strip()]\n\n    handled_categories = data.get("handled_categories", fallback["handled_categories"])\n    if isinstance(handled_categories, str):\n        handled_categories = [item.strip().lower() for item in handled_categories.split(",") if item.strip()]\n\n    status = str(data.get("status", fallback["status"])).lower()\n    if status not in {"idle", "available", "busy", "offline"}:\n        status = fallback["status"]\n\n    success_rate = float(data.get("success_rate", fallback["success_rate"]) or fallback["success_rate"])\n    if success_rate > 1:\n        success_rate = success_rate / 100\n\n    return {\n        "name": str(data.get("name", fallback["name"])),\n        "status": status,\n        "current_tasks": int(data.get("current_tasks", fallback["current_tasks"]) or fallback["current_tasks"]),\n        "max_tasks": int(data.get("max_tasks", fallback["max_tasks"]) or fallback["max_tasks"]),\n        "shift_start": str(data.get("shift_start", fallback["shift_start"])),\n        "shift_end": str(data.get("shift_end", fallback["shift_end"])),\n        "skills": skills,\n        "handled_categories": handled_categories,\n        "experience_level": int(data.get("experience_level", fallback["experience_level"]) or fallback["experience_level"]),\n        "success_rate": round(success_rate, 2),\n        "avg_resolution_minutes": float(data.get("avg_resolution_minutes", fallback["avg_resolution_minutes"]) or fallback["avg_resolution_minutes"]),\n        "source_provider": source_provider,\n        "llm_used": llm_used,\n    }\n\n\ndef generate_mock_task(provider: Optional[str] = None) -> Dict:\n    system_prompt = (\n        "You generate realistic customer support/service tasks for an AI workforce allocation demo."\n    )\n\n    user_prompt = """\nGenerate one realistic task for a service/customer-support task allocation system.\n\nReturn JSON with exactly:\n{\n  "title": string,\n  "description": string,\n  "priority": "urgent" | "high" | "medium" | "low",\n  "category": "payment" | "billing" | "technical" | "account" | "general",\n  "required_skills": string[],\n  "sla_minutes": number\n}\n\nMake it different every time.\n"""\n\n    result = generate_json_with_llm(system_prompt, user_prompt, provider=provider)\n\n    if result["ok"]:\n        return _normalize_task(result["data"], result["provider"], True)\n\n    fallback = random.choice(TASK_FALLBACKS)\n    normalized = _normalize_task(fallback, result["provider"], False)\n    normalized["fallback_reason"] = result["error"]\n    return normalized\n\n\ndef generate_mock_resource(provider: Optional[str] = None) -> Dict:\n    system_prompt = (\n        "You generate realistic support agents/resources for an AI workforce allocation demo."\n    )\n\n    user_prompt = """\nGenerate one realistic support agent/resource.\n\nReturn JSON with exactly:\n{\n  "name": string,\n  "status": "idle" | "available" | "busy" | "offline",\n  "current_tasks": number,\n  "max_tasks": number,\n  "shift_start": "HH:MM",\n  "shift_end": "HH:MM",\n  "skills": string[],\n  "handled_categories": string[],\n  "experience_level": number,\n  "success_rate": number,\n  "avg_resolution_minutes": number\n}\n\nUse realistic values. success_rate must be between 0 and 1.\nMake it different every time.\n"""\n\n    result = generate_json_with_llm(system_prompt, user_prompt, provider=provider)\n\n    if result["ok"]:\n        return _normalize_resource(result["data"], result["provider"], True)\n\n    fallback = random.choice(RESOURCE_FALLBACKS)\n    normalized = _normalize_resource(fallback, result["provider"], False)\n    normalized["fallback_reason"] = result["error"]\n    return normalized\n',
    'backend/app/main.py': '\nfrom typing import Optional\n\nfrom fastapi import FastAPI, HTTPException, Query\nfrom fastapi.middleware.cors import CORSMiddleware\n\nfrom .agentic_assignment_engine import assign_task_agentic\nfrom .analytics_engine import build_analytics_summary\nfrom .assignment_engine import assign_single_task, assign_tasks\nfrom .database import (\n    append_assignment_log,\n    get_db_status,\n    load_assignment_logs,\n    load_history,\n    load_resources,\n    load_tasks,\n    save_resources,\n)\nfrom .llm_provider import get_llm_status\nfrom .ml_ranking_model import (\n    append_candidate_training_rows,\n    assign_task_ml,\n    get_ml_status,\n    train_ml_model,\n)\nfrom .mock_generator import generate_mock_resource, generate_mock_task\nfrom .schemas import AssignmentRequest, ResourceIn, TaskIn\n\n\napp = FastAPI(\n    title="AI Task Allocation System",\n    description="Smart workforce task allocation using deterministic scoring, Agentic RAG, workflow traces, assignment history, trainable ML ranking, analytics, SQLite persistence, and multi-provider LLM support.",\n    version="1.7.0",\n)\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=["*"],\n    allow_credentials=True,\n    allow_methods=["*"],\n    allow_headers=["*"],\n)\n\n\ndef _next_resource_id(resources):\n    used_numbers = []\n    for resource in resources:\n        rid = str(resource.get("resource_id", "")).upper().replace("R", "")\n        if rid.isdigit():\n            used_numbers.append(int(rid))\n    return f"R{max(used_numbers, default=0) + 1}"\n\n\ndef _log_result(result):\n    append_assignment_log(result)\n    append_candidate_training_rows(result)\n\n\n@app.get("/")\ndef health_check():\n    return {\n        "status": "ok",\n        "app": "AI Task Allocation System",\n        "message": "Backend is running. Open /docs for API testing.",\n    }\n\n\n@app.get("/db/status")\ndef db_status():\n    return get_db_status()\n\n\n@app.get("/llm/status")\ndef llm_status():\n    return get_llm_status()\n\n\n@app.post("/mock/task")\ndef mock_task(provider: Optional[str] = Query(default=None)):\n    return generate_mock_task(provider=provider)\n\n\n@app.post("/mock/resource")\ndef mock_resource(provider: Optional[str] = Query(default=None)):\n    return generate_mock_resource(provider=provider)\n\n\n@app.get("/analytics/summary")\ndef analytics_summary(limit: int = Query(default=500, ge=1, le=2000)):\n    return build_analytics_summary(limit=limit)\n\n\n@app.get("/resources")\ndef get_resources():\n    return load_resources()\n\n\n@app.post("/resources")\ndef create_resource(resource: ResourceIn):\n    resources = load_resources()\n    data = resource.model_dump()\n\n    if not data["resource_id"]:\n        data["resource_id"] = _next_resource_id(resources)\n\n    if any(item["resource_id"] == data["resource_id"] for item in resources):\n        raise HTTPException(status_code=409, detail="Resource ID already exists.")\n\n    data["skills"] = [skill.strip().lower() for skill in data["skills"] if skill.strip()]\n    data["handled_categories"] = [\n        category.strip().lower()\n        for category in data["handled_categories"]\n        if category.strip()\n    ]\n    data["status"] = data["status"].lower()\n\n    resources.append(data)\n    save_resources(resources)\n\n    return {\n        "message": "Resource created successfully.",\n        "resource": data,\n    }\n\n\n@app.put("/resources/{resource_id}")\ndef update_resource(resource_id: str, resource: ResourceIn):\n    resources = load_resources()\n    data = resource.model_dump()\n    data["resource_id"] = resource_id\n    data["skills"] = [skill.strip().lower() for skill in data["skills"] if skill.strip()]\n    data["handled_categories"] = [\n        category.strip().lower()\n        for category in data["handled_categories"]\n        if category.strip()\n    ]\n    data["status"] = data["status"].lower()\n\n    for index, existing in enumerate(resources):\n        if existing["resource_id"] == resource_id:\n            resources[index] = data\n            save_resources(resources)\n            return {\n                "message": "Resource updated successfully.",\n                "resource": data,\n            }\n\n    raise HTTPException(status_code=404, detail="Resource not found.")\n\n\n@app.delete("/resources/{resource_id}")\ndef delete_resource(resource_id: str):\n    resources = load_resources()\n    remaining = [resource for resource in resources if resource["resource_id"] != resource_id]\n\n    if len(remaining) == len(resources):\n        raise HTTPException(status_code=404, detail="Resource not found.")\n\n    save_resources(remaining)\n\n    return {\n        "message": "Resource deleted successfully.",\n        "resource_id": resource_id,\n    }\n\n\n@app.get("/tasks")\ndef get_tasks():\n    return load_tasks()\n\n\n@app.get("/history")\ndef get_history():\n    return load_history()\n\n\n@app.get("/assignment-logs")\ndef get_assignment_logs(limit: int = Query(default=50, ge=1, le=500)):\n    return load_assignment_logs(limit=limit)\n\n\n@app.get("/ml/status")\ndef ml_status():\n    return get_ml_status()\n\n\n@app.post("/ml/train")\ndef ml_train():\n    return train_ml_model()\n\n\n@app.post("/assign")\ndef assign_task(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_single_task(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/agentic")\ndef assign_task_with_agentic_rag(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_task_agentic(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/ml")\ndef assign_task_with_ml_ranker(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_task_ml(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/batch")\ndef assign_batch(payload: AssignmentRequest):\n    result = assign_tasks(\n        [task.model_dump() for task in payload.tasks],\n        now_hhmm=payload.now_hhmm,\n    )\n\n    for item in result.get("assignments", []):\n        _log_result(item)\n\n    return result\n\n\n@app.post("/assign/sample")\ndef assign_sample(now_hhmm: Optional[str] = Query(default="10:30")):\n    result = assign_tasks(load_tasks(), now_hhmm=now_hhmm)\n\n    for item in result.get("assignments", []):\n        _log_result(item)\n\n    return result\n',
    'frontend/src/components/LLMPanel.jsx': '\nexport default function LLMPanel({ status }) {\n  if (!status) return null;\n\n  const ollama = status.providers?.ollama || {};\n  const openai = status.providers?.openai || {};\n  const gemini = status.providers?.gemini || {};\n\n  return (\n    <div className="card llmPanel">\n      <div className="dashboardHeader">\n        <div>\n          <h2>Multi-Provider LLM Layer</h2>\n          <p className="muted">\n            Used for mock task/resource generation and later for task parsing or explanation. Final assignment still comes from scoring + RAG + ML.\n          </p>\n        </div>\n\n        <div className={`modelBadge ${ollama.running ? "ready" : "notReady"}`}>\n          {ollama.running ? "Ollama Running" : "Ollama Offline"}\n        </div>\n      </div>\n\n      <div className="llmGrid">\n        <div>\n          <b>Default</b>\n          <span>{status.default_provider}</span>\n        </div>\n        <div>\n          <b>Ollama</b>\n          <span>{ollama.model}</span>\n          <small>{ollama.base_url}</small>\n        </div>\n        <div>\n          <b>OpenAI</b>\n          <span>{openai.configured ? "Configured" : "No API key"}</span>\n          <small>{openai.model}</small>\n        </div>\n        <div>\n          <b>Gemini</b>\n          <span>{gemini.configured ? "Configured" : "No API key"}</span>\n          <small>{gemini.model}</small>\n        </div>\n      </div>\n\n      {!ollama.running && (\n        <p className="warningText">\n          Ollama is not reachable. Mock buttons will still work using deterministic fallback data.\n        </p>\n      )}\n    </div>\n  );\n}\n',
    'frontend/src/components/TaskForm.jsx': '\nimport { useState } from "react";\n\nconst DEFAULT_TASK = {\n  title: "Customer payment failed",\n  description: "Customer says payment failed after checkout using card",\n  priority: "high",\n  category: "payment",\n  required_skills: "payments,billing,customer_support",\n  sla_minutes: 60,\n};\n\nexport default function TaskForm({\n  onAssign,\n  onAgenticAssign,\n  onMlAssign,\n  onGenerateMockTask,\n  loading,\n  agenticLoading,\n  mlLoading,\n  mockTaskLoading,\n}) {\n  const [task, setTask] = useState(DEFAULT_TASK);\n\n  function updateField(field, value) {\n    setTask((current) => ({\n      ...current,\n      [field]: value,\n    }));\n  }\n\n  async function fillMockTask() {\n    const mock = await onGenerateMockTask();\n    if (!mock) return;\n\n    setTask({\n      title: mock.title || "",\n      description: mock.description || "",\n      priority: mock.priority || "medium",\n      category: mock.category || "general",\n      required_skills: Array.isArray(mock.required_skills)\n        ? mock.required_skills.join(",")\n        : String(mock.required_skills || ""),\n      sla_minutes: mock.sla_minutes || 120,\n    });\n  }\n\n  function buildPayload() {\n    return {\n      task_id: `CUSTOM-${Date.now()}`,\n      title: task.title.trim(),\n      description: task.description.trim(),\n      priority: task.priority,\n      category: task.category.trim() || null,\n      required_skills: task.required_skills\n        .split(",")\n        .map((skill) => skill.trim().toLowerCase())\n        .filter(Boolean),\n      sla_minutes: Number(task.sla_minutes) || 120,\n    };\n  }\n\n  function submitTask(event) {\n    event.preventDefault();\n    onAssign(buildPayload());\n  }\n\n  function submitAgenticTask() {\n    onAgenticAssign(buildPayload());\n  }\n\n  function submitMlTask() {\n    onMlAssign(buildPayload());\n  }\n\n  const disabled = loading || agenticLoading || mlLoading || mockTaskLoading;\n\n  return (\n    <div className="card">\n      <div className="formHeader">\n        <div>\n          <h2>Assign a Custom Task</h2>\n          <p className="muted">\n            Normal assignment uses scoring. Agentic RAG retrieves similar cases and SOPs.\n            ML Ranker uses the trained model when available.\n          </p>\n        </div>\n\n        <button\n          type="button"\n          className="mockButton"\n          disabled={disabled}\n          onClick={fillMockTask}\n        >\n          {mockTaskLoading ? "Generating..." : "Generate Mock Task"}\n        </button>\n      </div>\n\n      <form className="taskForm" onSubmit={submitTask}>\n        <label>\n          Task title\n          <input\n            value={task.title}\n            onChange={(event) => updateField("title", event.target.value)}\n            placeholder="Example: Customer payment failed"\n            required\n          />\n        </label>\n\n        <label>\n          Description\n          <textarea\n            value={task.description}\n            onChange={(event) => updateField("description", event.target.value)}\n            placeholder="Describe what happened..."\n            rows={4}\n          />\n        </label>\n\n        <div className="formGrid">\n          <label>\n            Priority\n            <select\n              value={task.priority}\n              onChange={(event) => updateField("priority", event.target.value)}\n            >\n              <option value="urgent">urgent</option>\n              <option value="high">high</option>\n              <option value="medium">medium</option>\n              <option value="low">low</option>\n            </select>\n          </label>\n\n          <label>\n            Category\n            <input\n              value={task.category}\n              onChange={(event) => updateField("category", event.target.value)}\n              placeholder="payment, technical, billing..."\n            />\n          </label>\n\n          <label>\n            SLA minutes\n            <input\n              type="number"\n              value={task.sla_minutes}\n              onChange={(event) => updateField("sla_minutes", event.target.value)}\n              min="1"\n            />\n          </label>\n        </div>\n\n        <label>\n          Required skills\n          <input\n            value={task.required_skills}\n            onChange={(event) => updateField("required_skills", event.target.value)}\n            placeholder="payments,billing,customer_support"\n          />\n          <small>Use comma-separated skills.</small>\n        </label>\n\n        <div className="buttonRow three">\n          <button type="submit" disabled={disabled}>\n            {loading ? "Finding..." : "Normal Assignment"}\n          </button>\n\n          <button\n            type="button"\n            className="secondaryButton"\n            disabled={disabled}\n            onClick={submitAgenticTask}\n          >\n            {agenticLoading ? "Running RAG..." : "Agentic RAG Assignment"}\n          </button>\n\n          <button\n            type="button"\n            className="mlButton"\n            disabled={disabled}\n            onClick={submitMlTask}\n          >\n            {mlLoading ? "Running ML..." : "ML Ranker Assignment"}\n          </button>\n        </div>\n      </form>\n    </div>\n  );\n}\n',
    'frontend/src/components/ResourceForm.jsx': '\nimport { useState } from "react";\n\nconst DEFAULT_RESOURCE = {\n  name: "Sara",\n  status: "idle",\n  current_tasks: 0,\n  max_tasks: 3,\n  shift_start: "09:00",\n  shift_end: "18:00",\n  skills: "billing,payments,customer_support",\n  handled_categories: "payment,billing",\n  experience_level: 3,\n  success_rate_percent: 88,\n  avg_resolution_minutes: 45,\n};\n\nexport default function ResourceForm({ onCreate, onGenerateMockResource, loading, mockResourceLoading }) {\n  const [resource, setResource] = useState(DEFAULT_RESOURCE);\n\n  function updateField(field, value) {\n    setResource((current) => ({\n      ...current,\n      [field]: value,\n    }));\n  }\n\n  async function fillMockResource() {\n    const mock = await onGenerateMockResource();\n    if (!mock) return;\n\n    setResource({\n      name: mock.name || "",\n      status: mock.status || "idle",\n      current_tasks: mock.current_tasks ?? 0,\n      max_tasks: mock.max_tasks ?? 3,\n      shift_start: mock.shift_start || "09:00",\n      shift_end: mock.shift_end || "18:00",\n      skills: Array.isArray(mock.skills) ? mock.skills.join(",") : String(mock.skills || ""),\n      handled_categories: Array.isArray(mock.handled_categories)\n        ? mock.handled_categories.join(",")\n        : String(mock.handled_categories || ""),\n      experience_level: mock.experience_level || 3,\n      success_rate_percent: Math.round(Number(mock.success_rate || 0.85) * 100),\n      avg_resolution_minutes: mock.avg_resolution_minutes || 60,\n    });\n  }\n\n  function splitCsv(value) {\n    return value\n      .split(",")\n      .map((item) => item.trim().toLowerCase())\n      .filter(Boolean);\n  }\n\n  function submitResource(event) {\n    event.preventDefault();\n\n    const payload = {\n      resource_id: "",\n      name: resource.name.trim(),\n      status: resource.status,\n      current_tasks: Number(resource.current_tasks) || 0,\n      max_tasks: Number(resource.max_tasks) || 1,\n      shift_start: resource.shift_start,\n      shift_end: resource.shift_end,\n      skills: splitCsv(resource.skills),\n      handled_categories: splitCsv(resource.handled_categories),\n      experience_level: Number(resource.experience_level) || 3,\n      success_rate: Math.min(Math.max(Number(resource.success_rate_percent) || 85, 0), 100) / 100,\n      avg_resolution_minutes: Number(resource.avg_resolution_minutes) || 60,\n    };\n\n    onCreate(payload);\n\n    setResource((current) => ({\n      ...current,\n      name: "",\n    }));\n  }\n\n  return (\n    <div className="card">\n      <div className="formHeader">\n        <div>\n          <h2>Add Resource / Agent</h2>\n          <p className="muted">\n            Add a new support agent with skill, shift, workload, status, and performance data.\n          </p>\n        </div>\n\n        <button\n          type="button"\n          className="mockButton"\n          disabled={loading || mockResourceLoading}\n          onClick={fillMockResource}\n        >\n          {mockResourceLoading ? "Generating..." : "Generate Mock Resource"}\n        </button>\n      </div>\n\n      <form className="taskForm" onSubmit={submitResource}>\n        <div className="formGrid">\n          <label>\n            Name\n            <input\n              value={resource.name}\n              onChange={(event) => updateField("name", event.target.value)}\n              placeholder="Agent name"\n              required\n            />\n          </label>\n\n          <label>\n            Status\n            <select\n              value={resource.status}\n              onChange={(event) => updateField("status", event.target.value)}\n            >\n              <option value="idle">idle</option>\n              <option value="available">available</option>\n              <option value="busy">busy</option>\n              <option value="offline">offline</option>\n            </select>\n          </label>\n\n          <label>\n            Experience 1-5\n            <input\n              type="number"\n              min="1"\n              max="5"\n              value={resource.experience_level}\n              onChange={(event) => updateField("experience_level", event.target.value)}\n            />\n          </label>\n        </div>\n\n        <div className="formGrid">\n          <label>\n            Current tasks\n            <input\n              type="number"\n              min="0"\n              value={resource.current_tasks}\n              onChange={(event) => updateField("current_tasks", event.target.value)}\n            />\n          </label>\n\n          <label>\n            Max tasks\n            <input\n              type="number"\n              min="1"\n              value={resource.max_tasks}\n              onChange={(event) => updateField("max_tasks", event.target.value)}\n            />\n          </label>\n\n          <label>\n            Success %\n            <input\n              type="number"\n              min="0"\n              max="100"\n              value={resource.success_rate_percent}\n              onChange={(event) => updateField("success_rate_percent", event.target.value)}\n            />\n          </label>\n        </div>\n\n        <div className="formGrid">\n          <label>\n            Shift start\n            <input\n              type="time"\n              value={resource.shift_start}\n              onChange={(event) => updateField("shift_start", event.target.value)}\n            />\n          </label>\n\n          <label>\n            Shift end\n            <input\n              type="time"\n              value={resource.shift_end}\n              onChange={(event) => updateField("shift_end", event.target.value)}\n            />\n          </label>\n\n          <label>\n            Avg resolution minutes\n            <input\n              type="number"\n              min="1"\n              value={resource.avg_resolution_minutes}\n              onChange={(event) => updateField("avg_resolution_minutes", event.target.value)}\n            />\n          </label>\n        </div>\n\n        <label>\n          Skills\n          <input\n            value={resource.skills}\n            onChange={(event) => updateField("skills", event.target.value)}\n            placeholder="billing,payments,customer_support"\n          />\n        </label>\n\n        <label>\n          Handled categories\n          <input\n            value={resource.handled_categories}\n            onChange={(event) => updateField("handled_categories", event.target.value)}\n            placeholder="payment,billing,technical"\n          />\n        </label>\n\n        <button type="submit" disabled={loading}>\n          {loading ? "Adding..." : "Add Resource"}\n        </button>\n      </form>\n    </div>\n  );\n}\n',
    'frontend/src/App.jsx': '\nimport { useEffect, useState } from "react";\n\nimport { apiDelete, apiGet, apiPost } from "./api/client";\nimport AssignmentCard from "./components/AssignmentCard";\nimport AssignmentHistory from "./components/AssignmentHistory";\nimport Dashboard from "./components/Dashboard";\nimport LLMPanel from "./components/LLMPanel";\nimport MLPanel from "./components/MLPanel";\nimport ResourceForm from "./components/ResourceForm";\nimport ResourceTable from "./components/ResourceTable";\nimport TaskForm from "./components/TaskForm";\nimport TaskTable from "./components/TaskTable";\n\nfunction SingleAssignmentResult({ result }) {\n  if (!result) return null;\n\n  const title =\n    result.mode === "agentic_rag"\n      ? "Agentic RAG Assignment Result"\n      : result.mode === "ml_ranker" || result.mode === "ml_ranker_fallback"\n        ? "ML Ranker Assignment Result"\n        : "Custom Task Assignment Result";\n\n  return (\n    <div className="card">\n      <h2>{title}</h2>\n      <AssignmentCard item={result} />\n    </div>\n  );\n}\n\nfunction BatchAssignmentResult({ result }) {\n  if (!result) return null;\n\n  return (\n    <div className="card">\n      <h2>Sample Batch Assignment Result</h2>\n      <p>\n        Assigned {result.assigned_count} of {result.total_tasks} tasks.\n        Unassigned: {result.unassigned_count}.\n      </p>\n\n      <div className="results">\n        {result.assignments.map((item) => (\n          <AssignmentCard key={item.task.task_id} item={item} />\n        ))}\n      </div>\n    </div>\n  );\n}\n\nexport default function App() {\n  const [resources, setResources] = useState([]);\n  const [tasks, setTasks] = useState([]);\n  const [assignmentLogs, setAssignmentLogs] = useState([]);\n  const [mlStatus, setMlStatus] = useState(null);\n  const [llmStatus, setLlmStatus] = useState(null);\n  const [analytics, setAnalytics] = useState(null);\n  const [batchResult, setBatchResult] = useState(null);\n  const [singleResult, setSingleResult] = useState(null);\n  const [now, setNow] = useState("10:30");\n  const [loadingBatch, setLoadingBatch] = useState(false);\n  const [loadingSingle, setLoadingSingle] = useState(false);\n  const [loadingAgentic, setLoadingAgentic] = useState(false);\n  const [loadingMl, setLoadingMl] = useState(false);\n  const [loadingTrain, setLoadingTrain] = useState(false);\n  const [loadingResource, setLoadingResource] = useState(false);\n  const [loadingMockTask, setLoadingMockTask] = useState(false);\n  const [loadingMockResource, setLoadingMockResource] = useState(false);\n  const [error, setError] = useState("");\n\n  async function loadData() {\n    try {\n      const [resourceData, taskData, logsData, mlData, analyticsData, llmData] = await Promise.all([\n        apiGet("/resources"),\n        apiGet("/tasks"),\n        apiGet("/assignment-logs"),\n        apiGet("/ml/status"),\n        apiGet("/analytics/summary"),\n        apiGet("/llm/status"),\n      ]);\n\n      setResources(resourceData);\n      setTasks(taskData);\n      setAssignmentLogs(logsData);\n      setMlStatus(mlData);\n      setAnalytics(analyticsData);\n      setLlmStatus(llmData);\n    } catch (err) {\n      setError(err.message);\n    }\n  }\n\n  async function refreshRuntimeData() {\n    try {\n      const [logsData, mlData, analyticsData, llmData] = await Promise.all([\n        apiGet("/assignment-logs"),\n        apiGet("/ml/status"),\n        apiGet("/analytics/summary"),\n        apiGet("/llm/status"),\n      ]);\n      setAssignmentLogs(logsData);\n      setMlStatus(mlData);\n      setAnalytics(analyticsData);\n      setLlmStatus(llmData);\n    } catch (err) {\n      setError(err.message);\n    }\n  }\n\n  async function generateMockTask() {\n    setLoadingMockTask(true);\n    setError("");\n\n    try {\n      const data = await apiPost("/mock/task?provider=ollama");\n      if (!data.llm_used && data.fallback_reason) {\n        setError(`Mock task used fallback: ${data.fallback_reason}`);\n      }\n      return data;\n    } catch (err) {\n      setError(err.message);\n      return null;\n    } finally {\n      setLoadingMockTask(false);\n    }\n  }\n\n  async function generateMockResource() {\n    setLoadingMockResource(true);\n    setError("");\n\n    try {\n      const data = await apiPost("/mock/resource?provider=ollama");\n      if (!data.llm_used && data.fallback_reason) {\n        setError(`Mock resource used fallback: ${data.fallback_reason}`);\n      }\n      return data;\n    } catch (err) {\n      setError(err.message);\n      return null;\n    } finally {\n      setLoadingMockResource(false);\n    }\n  }\n\n  async function trainMlRanker() {\n    setLoadingTrain(true);\n    setError("");\n\n    try {\n      const data = await apiPost("/ml/train");\n      setMlStatus(data.status || data);\n      await refreshRuntimeData();\n      if (!data.trained) {\n        setError(data.message);\n      }\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingTrain(false);\n    }\n  }\n\n  async function createResource(payload) {\n    setLoadingResource(true);\n    setError("");\n\n    try {\n      await apiPost("/resources", payload);\n      await loadData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingResource(false);\n    }\n  }\n\n  async function deleteResource(resourceId) {\n    const confirmed = window.confirm("Delete this resource?");\n    if (!confirmed) return;\n\n    setError("");\n\n    try {\n      await apiDelete(`/resources/${resourceId}`);\n      await loadData();\n    } catch (err) {\n      setError(err.message);\n    }\n  }\n\n  async function runSampleAssignment() {\n    setLoadingBatch(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign/sample?now_hhmm=${encodeURIComponent(now)}`);\n      setBatchResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingBatch(false);\n    }\n  }\n\n  async function runCustomAssignment(taskPayload) {\n    setLoadingSingle(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign?now_hhmm=${encodeURIComponent(now)}`, taskPayload);\n      setSingleResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingSingle(false);\n    }\n  }\n\n  async function runAgenticAssignment(taskPayload) {\n    setLoadingAgentic(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign/agentic?now_hhmm=${encodeURIComponent(now)}`, taskPayload);\n      setSingleResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingAgentic(false);\n    }\n  }\n\n  async function runMlAssignment(taskPayload) {\n    setLoadingMl(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign/ml?now_hhmm=${encodeURIComponent(now)}`, taskPayload);\n      setSingleResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingMl(false);\n    }\n  }\n\n  useEffect(() => {\n    loadData();\n  }, []);\n\n  return (\n    <main className="app">\n      <section className="hero">\n        <div>\n          <h1>AI Task Allocation System</h1>\n          <p>\n            Assign service/support tasks using deterministic scoring, Agentic RAG retrieval,\n            workflow traces, assignment history, ML ranking, SQLite, analytics, and optional LLM providers.\n          </p>\n        </div>\n\n        <div className="controls">\n          <label>\n            Demo time{" "}\n            <input value={now} onChange={(event) => setNow(event.target.value)} />\n          </label>\n          <button onClick={runSampleAssignment} disabled={loadingBatch}>\n            {loadingBatch ? "Assigning..." : "Run Sample Batch"}\n          </button>\n        </div>\n      </section>\n\n      {error && <div className="error">{error}</div>}\n\n      <section className="grid">\n        <Dashboard analytics={analytics} />\n        <LLMPanel status={llmStatus} />\n\n        <TaskForm\n          onAssign={runCustomAssignment}\n          onAgenticAssign={runAgenticAssignment}\n          onMlAssign={runMlAssignment}\n          onGenerateMockTask={generateMockTask}\n          loading={loadingSingle}\n          agenticLoading={loadingAgentic}\n          mlLoading={loadingMl}\n          mockTaskLoading={loadingMockTask}\n        />\n\n        <SingleAssignmentResult result={singleResult} />\n\n        <MLPanel status={mlStatus} onTrain={trainMlRanker} loading={loadingTrain} />\n\n        <AssignmentHistory logs={assignmentLogs} />\n\n        <ResourceForm\n          onCreate={createResource}\n          onGenerateMockResource={generateMockResource}\n          loading={loadingResource}\n          mockResourceLoading={loadingMockResource}\n        />\n        <ResourceTable resources={resources} onDelete={deleteResource} />\n\n        <TaskTable tasks={tasks} />\n\n        <BatchAssignmentResult result={batchResult} />\n      </section>\n    </main>\n  );\n}\n',
    'backend/.env.example': '\n# LLM provider can be: off, ollama, openai, gemini\nLLM_PROVIDER=ollama\n\n# Ollama local config\nOLLAMA_BASE_URL=http://localhost:11434\nOLLAMA_MODEL=llama3.1\n\n# OpenAI optional config\nOPENAI_API_KEY=\nOPENAI_MODEL=gpt-4o-mini\n\n# Gemini optional config\nGEMINI_API_KEY=\nGEMINI_MODEL=gemini-1.5-flash\n',
}

